export const steps: Step[] = [
  { text: { en: "Stay calm and act straight away.", sl: "Ostanite mirni in ukrepajte takoj.", de: "Bleiben Sie ruhig und handeln Sie sofort.", fr: "Restez calme et agissez immédiatement.", es: "Mantén la calma y actúa de inmediato.", it: "Mantieni la calma e agisci subito.", pt: "Mantém a calma e age de imediato.", nl: "Blijf rustig en kom meteen in actie.", pl: "Zachowaj spokój i działaj od razu.", cs: "Zachovejte klid a jednejte okamžitě.", hr: "Zadrži smirenost i odmah djeluj.", sv: "Håll dig lugn och agera direkt.", da: "Bevar roen, og handl med det samme.", fi: "Pysy rauhallisena ja toimi heti.", nb: "Hold deg rolig, og handle med en gang." }, sources: [RSPCA, ASPCA] },
  { text: { en: "Move your pet away from the substance.", sl: "Hišnega ljubljenčka umaknite od snovi.", de: "Bringen Sie Ihr Haustier weg von dem Stoff.", fr: "Éloignez votre animal de la substance.", es: "Aleja a tu mascota de la sustancia.", it: "Allontana l’animale dalla sostanza.", pt: "Afasta o teu animal da substância.", nl: "Haal je huisdier weg bij de stof.", pl: "Odsuń zwierzę od substancji.", cs: "Odveďte zvíře z dosahu látky.", hr: "Odmakni ljubimca od te tvari.", sv: "Flytta bort ditt djur från ämnet.", da: "Få dit dyr væk fra stoffet.", fi: "Siirrä lemmikkisi kauemmas aineesta.", nb: "Få dyret bort fra stoffet." }, sources: [RSPCA, PPH] },
  { text: { en: "Check that your pet is breathing and acting normally.", sl: "Preverite, ali vaš ljubljenček diha in se vede običajno.", de: "Prüfen Sie, ob Ihr Haustier atmet und sich normal verhält.", fr: "Vérifiez que votre animal respire et se comporte normalement.", es: "Comprueba que tu mascota respira y se comporta con normalidad.", it: "Controlla che l’animale respiri e si comporti normalmente.", pt: "Verifica se o teu animal está a respirar e a comportar-se normalmente.", nl: "Controleer of je huisdier ademt en zich normaal gedraagt.", pl: "Sprawdź, czy zwierzę oddycha i zachowuje się normalnie.", cs: "Zkontrolujte, zda zvíře dýchá a chová se normálně.", hr: "Provjeri diše li ljubimac i ponaša li se kao i inače.", sv: "Kontrollera att ditt djur andas och beter sig som vanligt.", da: "Tjek at dit dyr trækker vejret og opfører sig normalt.", fi: "Tarkista, että lemmikkisi hengittää ja käyttäytyy normaalisti.", nb: "Sjekk at dyret puster og oppfører seg normalt." }, sources: [PPH] },
  { text: { en: "Call your vet or an animal poison line right away. Tell them what happened, when and where.", sl: "Takoj pokličite veterinarja ali telefonsko linijo za zastrupitve živali. Povejte, kaj se je zgodilo, kdaj in kje.", de: "Rufen Sie sofort Ihren Tierarzt oder einen Giftnotruf für Tiere an. Schildern Sie, was wann und wo passiert ist.", fr: "Appelez immédiatement votre vétérinaire ou un centre antipoison vétérinaire. Expliquez ce qui s’est passé, quand et où.", es: "Llama enseguida a tu veterinario o a una línea de información toxicológica para animales. Explica qué ha pasado, cuándo y dónde.", it: "Chiama subito il veterinario o un centro antiveleni veterinario. Spiega cosa è successo, quando e dove.", pt: "Liga imediatamente ao teu veterinário ou a uma linha de apoio toxicológico para animais. Explica o que aconteceu, quando e onde.", nl: "Bel meteen je dierenarts of een vergiftigingenlijn voor dieren. Vertel wat er is gebeurd, wanneer en waar.", pl: "Natychmiast zadzwoń do weterynarza lub na telefon informacji toksykologicznej dla zwierząt. Powiedz, co się stało, kiedy i gdzie.", cs: "Ihned zavolejte veterináři nebo na toxikologickou linku pro zvířata. Řekněte, co se stalo, kdy a kde.", hr: "Odmah nazovi veterinara ili telefonsku liniju za otrovanja životinja. Reci što se dogodilo, kada i gdje.", sv: "Ring din veterinär eller en giftrådgivning för djur direkt. Berätta vad som har hänt, när och var.", da: "Ring straks til din dyrlæge eller en giftrådgivning for dyr. Fortæl hvad der er sket, hvornår og hvor.", fi: "Soita heti eläinlääkärille tai eläinten myrkytysneuvontaan. Kerro, mitä tapahtui, milloin ja missä.", nb: "Kontakt dyrlegen eller giftinformasjon for dyr med en gang. Fortell hva som har skjedd, når og hvor." }, sources: [RSPCA, PDSA, ICC] },
  { text: { en: "Do not wait for signs of illness — call even if your pet seems fine.", sl: "Ne čakajte, da se pojavijo znaki bolezni – pokličite, tudi če se ljubljenček zdi v redu.", de: "Warten Sie nicht auf Krankheitsanzeichen – rufen Sie auch an, wenn Ihr Haustier gesund wirkt.", fr: "N’attendez pas l’apparition de signes de maladie – appelez même si votre animal semble bien aller.", es: "No esperes a que aparezcan signos de enfermedad: llama aunque tu mascota parezca estar bien.", it: "Non aspettare che compaiano sintomi di malattia: chiama anche se l’animale sembra stare bene.", pt: "Não esperes por sinais de doença – liga mesmo que o teu animal pareça estar bem.", nl: "Wacht niet op verschijnselen van ziekte – bel ook als je huisdier er goed uitziet.", pl: "Nie czekaj na objawy choroby – zadzwoń, nawet jeśli zwierzę wydaje się zdrowe.", cs: "Nečekejte na příznaky onemocnění – zavolejte, i když se zvíře zdá v pořádku.", hr: "Ne čekaj da se pojave znakovi bolesti – nazovi i ako ljubimac djeluje dobro.", sv: "Vänta inte på tecken på sjukdom – ring även om ditt djur verkar må bra.", da: "Vent ikke på symptomer – ring også selv om dit dyr ser ud til at have det fint.", fi: "Älä odota sairauden oireita – soita, vaikka lemmikkisi vaikuttaisi voivan hyvin.", nb: "Ikke vent på symptomer – ring selv om dyret virker friskt." }, sources: [PDSA, ASPCA] },
  { text: { en: "Do not make your pet vomit unless a vet tells you to. It can do more harm than good.", sl: "Ljubljenčka ne silite v bruhanje, razen če vam to naroči veterinar. Lahko naredi več škode kot koristi.", de: "Lösen Sie bei Ihrem Haustier kein Erbrechen aus, es sei denn, ein Tierarzt weist Sie dazu an. Das kann mehr schaden als nützen.", fr: "Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande. Cela peut faire plus de mal que de bien.", es: "No provoques el vómito a tu mascota salvo que te lo indique un veterinario. Puede hacer más mal que bien.", it: "Non far vomitare l’animale, a meno che non te lo dica un veterinario. Può fare più male che bene.", pt: "Não faças o teu animal vomitar, a não ser que um veterinário te diga para o fazeres. Pode fazer mais mal do que bem.", nl: "Laat je huisdier niet overgeven, tenzij een dierenarts dat zegt. Dat kan meer kwaad dan goed doen.", pl: "Nie wywołuj u zwierzęcia wymiotów, chyba że zaleci to weterynarz. Może to bardziej zaszkodzić, niż pomóc.", cs: "Nevyvolávejte u zvířete zvracení, pokud vám to neřekne veterinář. Může to víc uškodit než pomoci.", hr: "Ne izazivaj povraćanje kod ljubimca, osim ako ti to kaže veterinar. Može više naštetiti nego pomoći.", sv: "Få inte ditt djur att kräkas om inte en veterinär säger åt dig att göra det. Det kan göra mer skada än nytta.", da: "Prøv ikke selv at få dit dyr til at kaste op medmindre en dyrlæge beder dig om det. Det kan gøre mere skade end gavn.", fi: "Älä yritä itse oksennuttaa lemmikkiäsi, ellei eläinlääkäri neuvo tekemään niin. Siitä voi olla enemmän haittaa kuin hyötyä.", nb: "Ikke prøv å få dyret til å kaste opp selv, med mindre en dyrlege ber deg om det. Det kan gjøre mer skade enn nytte." }, sources: [PPH, RSPCA, PDSA] },
  { text: { en: "Do not give home remedies such as salt water, and don't act on random tips from the internet.", sl: "Ljubljenčku ne dajajte domačih sredstev, kot je slana voda, in ne ravnajte po naključnih nasvetih z interneta.", de: "Geben Sie keine Hausmittel wie Salzwasser und verlassen Sie sich nicht auf irgendwelche Tipps aus dem Internet.", fr: "Ne donnez pas de remède maison comme de l’eau salée, et ne suivez pas de conseils trouvés au hasard sur Internet.", es: "No le des remedios caseros como agua con sal ni sigas cualquier consejo que encuentres en internet.", it: "Non dare rimedi casalinghi come l’acqua salata e non seguire consigli trovati a caso su internet.", pt: "Não dês remédios caseiros, como água com sal, e não sigas dicas aleatórias da internet.", nl: "Geef geen huismiddeltjes zoals zout water en ga niet af op willekeurige tips van internet.", pl: "Nie podawaj domowych środków, takich jak słona woda, i nie kieruj się przypadkowymi radami z internetu.", cs: "Nepodávejte domácí prostředky, jako je slaná voda, a neřiďte se náhodnými radami z internetu.", hr: "Ne daj ljubimcu kućne lijekove, poput slane vode, i ne slijedi nasumične savjete s interneta.", sv: "Ge inga huskurer som saltvatten, och följ inte vilka tips som helst från internet.", da: "Giv ikke huskure som saltvand, og følg ikke tilfældige råd fra internettet.", fi: "Älä anna kotikonsteja, kuten suolavettä, äläkä toimi satunnaisten netistä löytyneiden vinkkien mukaan.", nb: "Ikke gi huskurer som saltvann, og ikke følg tilfeldige råd fra internett." }, sources: [PPH, RSPCA, ASPCA] },
  { text: { en: "Note what your pet ate, roughly how much and when.", sl: "Zapišite si, kaj je ljubljenček pojedel, približno koliko in kdaj.", de: "Notieren Sie, was Ihr Haustier gefressen hat, ungefähr wie viel und wann.", fr: "Notez ce que votre animal a mangé, en quelle quantité approximative et à quel moment.", es: "Apunta qué ha comido tu mascota, más o menos cuánto y cuándo.", it: "Annota cosa ha mangiato l’animale, più o meno quanto e quando.", pt: "Anota o que o teu animal comeu, mais ou menos quanto e quando.", nl: "Schrijf op wat je huisdier heeft gegeten, ongeveer hoeveel en wanneer.", pl: "Zapisz, co zwierzę zjadło, mniej więcej ile i kiedy.", cs: "Poznamenejte si, co zvíře snědlo, zhruba kolik a kdy.", hr: "Zapiši što je ljubimac pojeo, otprilike koliko i kada.", sv: "Skriv upp vad ditt djur har ätit, ungefär hur mycket och när.", da: "Skriv ned hvad dit dyr har spist, cirka hvor meget og hvornår.", fi: "Kirjaa ylös, mitä lemmikkisi söi, suunnilleen kuinka paljon ja milloin.", nb: "Skriv ned hva dyret har spist, omtrent hvor mye og når." }, sources: [RSPCA, ASPCA] },
  { text: { en: "If you can do it safely, take the packaging, label, plant or substance with you to the vet.", sl: "Če je to varno, s seboj k veterinarju vzemite embalažo, etiketo, rastlino ali snov.", de: "Wenn es gefahrlos möglich ist, nehmen Sie Verpackung, Etikett, Pflanze oder Substanz mit zum Tierarzt.", fr: "Si vous pouvez le faire sans danger, apportez l’emballage, l’étiquette, la plante ou la substance chez le vétérinaire.", es: "Si puedes hacerlo sin riesgo, lleva al veterinario el envase, la etiqueta, la planta o la sustancia.", it: "Se puoi farlo senza rischi, porta dal veterinario la confezione, l’etichetta, la pianta o la sostanza.", pt: "Se o puderes fazer em segurança, leva contigo ao veterinário a embalagem, o rótulo, a planta ou a substância.", nl: "Als het veilig kan, neem dan de verpakking, het etiket, de plant of de stof mee naar de dierenarts.", pl: "Jeśli możesz to zrobić bezpiecznie, zabierz do weterynarza opakowanie, etykietę, roślinę lub substancję.", cs: "Pokud to jde bezpečně, vezměte s\u00a0sebou k\u00a0veterináři obal, etiketu, rostlinu nebo látku.", hr: "Ako je to sigurno, ponesi veterinaru ambalažu, etiketu, biljku ili tvar.", sv: "Om du kan göra det utan risk: ta med förpackningen, etiketten, växten eller ämnet till veterinären.", da: "Hvis du kan gøre det sikkert, så tag emballagen, etiketten, planten eller stoffet med til dyrlægen.", fi: "Jos voit tehdä sen turvallisesti, ota pakkaus, tuoteseloste, kasvi tai aine mukaan eläinlääkärille.", nb: "Hvis du kan gjøre det trygt, ta med emballasjen, etiketten, planten eller stoffet til dyrlegen." }, sources: [RSPCA, ICC] },
];

